fn lines_of(text: str) -> [str] {
    let parts = str_split(text, "\n")
    let out = arr_repeat("", 0)
    for i in 0..len(parts) {
        let l = str_trim(parts[i])
        if len(l) > 0 {
            out = arr_push(out, l)
        }
    }
    out
}

fn cmp_rows(a: (str, i64), b: (str, i64)) -> i64 {
    if a.1 > b.1 {
        -1
    } else if a.1 < b.1 {
        1
    } else {
        str_cmp(a.0, b.0)
    }
}

fn main() -> i64 {
    let ctext = match read_file("./data/customers.csv") {
        Ok(t) => t
        Err(e) => {
            eprintln("cannot read customers: {e}")
            return 2
        }
    }
    let otext = match read_file("./data/orders.csv") {
        Ok(t) => t
        Err(e) => {
            eprintln("cannot read orders: {e}")
            return 2
        }
    }

    let names = dict_new()
    let clines = lines_of(ctext)
    for i in 0..len(clines) {
        let line = clines[i]
        let c = str_index_of(line, ",")
        if c >= 0 {
            let id = str_trim(str_slice(line, 0, c))
            let name = str_trim(str_slice(line, c + 1, len(line)))
            if dict_has(names, id) == false {
                dict_set(names, id, name)
            }
        }
    }

    let seen = dict_new()
    let totals = dict_new()
    let unmatched = 0
    let olines = lines_of(otext)
    for i in 0..len(olines) {
        let f = str_split(olines[i], ",")
        if len(f) >= 3 {
            let oid = str_trim(f[0])
            let cid = str_trim(f[1])
            let amt = parse_int_or(str_trim(f[2]), 0)
            if dict_has(seen, oid) == false {
                dict_set(seen, oid, "1")
                if dict_has(names, cid) == false {
                    unmatched = unmatched + 1
                }
                if dict_has(totals, cid) == false {
                    dict_set(totals, cid, amt)
                } else {
                    dict_set(totals, cid, dict_get_or(totals, cid, 0) + amt)
                }
            }
        }
    }

    let rows = arr_repeat(("", 0), 0)
    let keys = dict_keys(totals)
    for i in 0..len(keys) {
        let k = keys[i]
        if dict_has(names, k) {
            rows = arr_push(rows, (dict_get_or(names, k, ""), dict_get_or(totals, k, 0)))
        }
    }

    let sorted = arr_sort_by(rows, |a, b| cmp_rows(a, b))

    let out = ""
    for i in 0..len(sorted) {
        let r = sorted[i]
        out = out + r.0 + ": " + to_str(r.1) + "\n"
    }
    out = out + "unmatched: " + to_str(unmatched) + "\n"

    match write_file("./out/report.txt", out) {
        Ok(_) => 0
        Err(e) => {
            eprintln("cannot write: {e}")
            1
        }
    }
}

